default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Connect' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('RequirePinForPairing', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_require_pin_for_pairing)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\Connect [RequirePinForPairing]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Connect')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Connect' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Connect' -Name 'RequirePinForPairing' -Value $ODV_require_pin_for_pairing -PropertyType DWord -Force | Out-Null
exit 0
